"""
Threat Hunting Notebook Tools (Demo-only, local-only).

Render a readable Markdown investigation report and persist hunt artifacts:
- case_state.json
- evidence.jsonl
- investigation.md

Output location: outputs/hunts/<entity>_<timestamp>/
"""

from __future__ import annotations

import json
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional


# Default output base directory (healthcare threat hunting dataset, regardless of which
# input dataset — canonical or enriched — was investigated)
DEFAULT_OUTPUT_BASE = "data/hc_threat_hunting_demo/outputs/hunts"


def _utcnow_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def _generate_hunt_folder_name(entity: str, timestamp: Optional[str] = None) -> str:
    """Generate a descriptive folder name for a hunt: <entity>_<YYYYMMDD_HHMMSS>"""
    # Sanitize entity name (remove special characters)
    safe_entity = "".join(c if c.isalnum() or c in "_-" else "_" for c in str(entity))
    
    # Use provided timestamp or current time
    if timestamp:
        try:
            # Try to parse ISO timestamp
            dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
            ts_str = dt.strftime("%Y%m%d_%H%M%S")
        except (ValueError, AttributeError):
            ts_str = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    else:
        ts_str = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    
    return f"{safe_entity}_{ts_str}"


def _safe_json(obj: Any) -> str:
    return json.dumps(obj, indent=2, default=str)


def _md_escape(s: Any) -> str:
    return str(s).replace("\n", " ").strip()


def build_evidence_log(case_state: Dict[str, Any]) -> Dict[str, Any]:
    """
    Build/refresh `case_state.evidence_log` by collecting unique event references found in:
    - baseline flags evidence
    - episode key events
    - pivot evidence

    Produces stable evidence ids in the form E-0001, E-0002, ...
    """
    try:
        seen = set()
        collected: List[Dict[str, Any]] = []

        def add_ref(event_id: Optional[str], table: Optional[str], timestamp: Optional[str], reason: str):
            if not event_id:
                return
            key = (event_id, table or "", timestamp or "", reason)
            if key in seen:
                return
            seen.add(key)
            collected.append(
                {
                    "event_id": event_id,
                    "table": table,
                    "timestamp": timestamp,
                    "reason_used": reason,
                }
            )

        for f in (case_state.get("baseline", {}).get("flags", []) or []):
            for ev in (f.get("evidence", []) or []):
                add_ref(ev.get("event_id"), ev.get("table"), ev.get("timestamp"), f"baseline:{f.get('flag_type')}")

        for ep in (case_state.get("timeline", {}).get("episodes", []) or []):
            for kev in (ep.get("key_events", []) or []):
                raw = kev.get("raw_ref") or {}
                add_ref(kev.get("event_id"), raw.get("table"), kev.get("ts"), f"episode:{ep.get('episode_id')}")

        for p in (case_state.get("pivots", []) or []):
            for ev in (p.get("evidence", []) or []):
                add_ref(ev.get("event_id"), ev.get("table"), ev.get("timestamp"), f"pivot:{p.get('pivot_id')}")

        # assign evidence ids (DEMO MODE: Cap to 5 evidence items)
        evidence_log = []
        for i, row in enumerate(collected[:5], start=1):
            evidence_log.append({"evidence_id": f"E-{i:04d}", **row})

        case_state = dict(case_state)
        case_state["evidence_log"] = evidence_log

        return {
            "success": True,
            "message": f"Built evidence log with {len(evidence_log)} item(s)",
            "data": {"case_state": case_state, "evidence_log": evidence_log},
        }
    except Exception as e:
        return {"success": False, "message": f"Error building evidence log: {e}", "data": None}


def render_investigation_markdown(case_state: Dict[str, Any]) -> Dict[str, Any]:
    """
    Render the investigation Markdown report from the case state.
    """
    try:
        hunt_id = case_state.get("hunt_id", "hunt-unknown")
        req = case_state.get("request", {})
        resolved = case_state.get("resolved_entity", {})
        # Distinguish "baseline key missing" (data loss upstream — case_state
        # was not passed through intact) from "baseline present but no flags"
        # (baseline was actually checked and came back clean). Collapsing both
        # to {} made this report claim "no significant deviations" even when
        # baseline was never analyzed at all.
        baseline_provided = "baseline" in case_state
        baseline = case_state.get("baseline") or {}
        timeline = case_state.get("timeline", {})
        risk = case_state.get("risk", {})
        pivots = case_state.get("pivots", [])
        evidence_log = case_state.get("evidence_log", [])

        lines: List[str] = []
        lines += [
            f"# Threat Hunting Investigation Report",
            "",
            f"**Hunt ID**: `{hunt_id}`",
            f"**Generated at**: `{_utcnow_iso()}`",
            "",
            "## Executive Summary",
            "",
            f"This hunt investigated suspected misuse of service account **{_md_escape(req.get('seed_entity'))}** "
            f"within `{_md_escape(req.get('start_ts'))}` to `{_md_escape(req.get('end_ts'))}`.",
            "",
            f"**Risk judgement**: **{_md_escape(risk.get('judgement', 'Unknown'))}** "
            f"(score `{_md_escape(risk.get('score_0_100', 'n/a'))}`)",
            "",
            "## Scope",
            "",
            f"- **Seed entity**: `{_md_escape(req.get('seed_entity'))}`",
            f"- **Time window**: `{_md_escape(req.get('start_ts'))}` → `{_md_escape(req.get('end_ts'))}`",
            f"- **Dataset**: `{_md_escape(req.get('dataset_root'))}`",
            "",
            "## Entity Profile (Resolved)",
            "",
            f"- **Entity ID**: `{_md_escape(resolved.get('entity_id'))}`",
            f"- **Type**: `{_md_escape(resolved.get('entity_type'))}`",
        ]

        profile = resolved.get("profile", {}) or {}
        if profile:
            lines += [
                "",
                "### Profile",
                "",
                f"- **Owner/team**: `{_md_escape(profile.get('owner_team', profile.get('department', 'unknown')))}`",
                f"- **Privilege**: `{_md_escape(profile.get('privilege_level', 'unknown'))}`",
            ]

        flags = baseline.get("flags", []) or []
        lines += [
            "",
            "## Entity Baseline Findings",
            "",
        ]
        if not baseline_provided:
            lines += ["Baseline data was not provided to this report — no comparison was performed.", ""]
        elif not flags:
            lines += ["No significant deviations were detected in the baseline comparison for this window.", ""]
        else:
            for f in flags:
                lines += [
                    f"- **{_md_escape(f.get('flag_type'))}**: {_md_escape(f.get('why'))} "
                    f"(confidence: `{_md_escape(f.get('confidence'))}`)",
                ]
                evs = f.get("evidence", []) or []
                if evs:
                    lines += [f"  - Evidence: " + ", ".join([f"`{_md_escape(e.get('event_id'))}`" for e in evs[:3]])]

        episodes = timeline.get("episodes", []) or []
        lines += [
            "",
            "## Investigation Timeline (Episodes)",
            "",
        ]
        if not episodes:
            lines += ["No episodes were produced (no events collected).", ""]
        else:
            for ep in episodes:
                lines += [
                    f"### {ep.get('episode_id', '')}: {_md_escape(ep.get('title', 'Episode'))}",
                    "",
                    f"- **Time range**: `{_md_escape(ep.get('start_ts'))}` → `{_md_escape(ep.get('end_ts'))}`",
                ]
                if ep.get("summary"):
                    lines += [f"- **Summary**: {_md_escape(ep.get('summary'))}"]
                if ep.get("entities_touched"):
                    lines += [f"- **Entities touched**: {', '.join([f'`{_md_escape(x)}`' for x in ep.get('entities_touched')[:12]])}"]
                lines += ["", "**Key events**:"]
                for kev in (ep.get("key_events", []) or [])[:6]:
                    eid = kev.get("event_id")
                    ts = kev.get("ts")
                    cat = kev.get("event_category")
                    action = kev.get("event_action")
                    host = kev.get("host")
                    res = kev.get("resource")
                    lines += [
                        f"- `{_md_escape(ts)}` `{_md_escape(eid)}` "
                        f"**{_md_escape(cat)}** `{_md_escape(action)}` "
                        f"(host=`{_md_escape(host)}`, resource=`{_md_escape(res)}`)",
                    ]

                lines += [""]

        lines += [
            "## Risk Assessment",
            "",
            f"- **Judgement**: **{_md_escape(risk.get('judgement', 'Unknown'))}**",
            f"- **Score**: `{_md_escape(risk.get('score_0_100', 'n/a'))}`",
            "",
            f"{_md_escape(risk.get('explanation', ''))}",
            "",
        ]
        rules = risk.get("rules_fired", []) or []
        if rules:
            lines += ["### Rules fired", ""]
            for r in rules:
                lines += [
                    f"- **{_md_escape(r.get('rule'))}** (+{_md_escape(r.get('points'))}): {_md_escape(r.get('why'))}",
                ]

        # Exactly three pivots
        lines += [
            "",
            "## Next Pivots (Exactly Three)",
            "",
        ]
        for p in (pivots or [])[:3]:
            lines += [
                f"### {_md_escape(p.get('pivot_id'))}: {_md_escape(p.get('title'))}",
                "",
                f"- **Why**: {_md_escape(p.get('why'))}",
                f"- **How (query hint)**:",
                "",
                "```json",
                _safe_json(p.get("query_hint", {})),
                "```",
            ]
            if p.get("evidence"):
                lines += [f"- **Evidence**: " + ", ".join([f"`{_md_escape(e.get('event_id'))}`" for e in p.get("evidence")[:3]])]
            lines += [""]

        lines += [
            "## Evidence Appendix",
            "",
        ]
        if not evidence_log:
            lines += ["No evidence pointers were recorded.", ""]
        else:
            lines += ["| Evidence ID | Event ID | Table | Timestamp | Reason |", "|---|---|---|---|---|"]
            for e in evidence_log:
                lines += [
                    f"| `{_md_escape(e.get('evidence_id'))}` | `{_md_escape(e.get('event_id'))}` | "
                    f"`{_md_escape(e.get('table'))}` | `{_md_escape(e.get('timestamp'))}` | {_md_escape(e.get('reason_used'))} |"
                ]
            lines += [""]

        md = "\n".join(lines)
        return {"success": True, "message": "Rendered investigation markdown", "data": {"markdown": md}}
    except Exception as e:
        return {"success": False, "message": f"Error rendering markdown: {e}", "data": None}


def write_hunt_artifacts(case_state: Dict[str, Any], out_dir: Optional[str] = None) -> Dict[str, Any]:
    """
    Persist hunt artifacts to disk under out_dir.
    
    If out_dir is not provided, automatically generates a folder name under outputs/hunts/
    using the format: <entity>_<YYYYMMDD_HHMMSS>
    
    Example: outputs/hunts/svc_backup1_20250108_161233/
    
    Args:
        case_state: The complete case state with baseline, timeline, risk, and pivots
        out_dir: Optional output directory. If not provided, auto-generates under outputs/hunts/
        
    Returns:
        Dict with success status and paths to written files
    """
    try:
        # Auto-generate folder name if not provided
        if not out_dir:
            # Extract entity from case_state
            entity = (
                case_state.get("request", {}).get("seed_entity") or
                case_state.get("resolved_entity", {}).get("entity_id") or
                case_state.get("hunt_id") or
                "unknown_entity"
            )
            # Extract timestamp from request or use current time
            timestamp = case_state.get("request", {}).get("end_ts")
            
            # Generate folder name
            folder_name = _generate_hunt_folder_name(entity, timestamp)
            out_dir = f"{DEFAULT_OUTPUT_BASE}/{folder_name}"
        
        out = Path(out_dir)
        out.mkdir(parents=True, exist_ok=True)

        # Update hunt_id in case_state to match folder name
        case_state = dict(case_state)
        if "hunt_id" not in case_state or not case_state["hunt_id"]:
            case_state["hunt_id"] = out.name
        
        # Add artifact metadata
        case_state["artifacts"] = {
            "generated_at": _utcnow_iso(),
            "output_dir": str(out.resolve()),
        }

        # Render markdown
        rendered = render_investigation_markdown(case_state)
        if not rendered["success"]:
            return rendered
        md = rendered["data"]["markdown"]

        # Evidence log in JSONL
        evidence_path = out / "evidence.jsonl"
        with open(evidence_path, "w", encoding="utf-8") as f:
            for row in case_state.get("evidence_log", []) or []:
                f.write(json.dumps(row, default=str) + "\n")

        case_state_path = out / "case_state.json"
        with open(case_state_path, "w", encoding="utf-8") as f:
            json.dump(case_state, f, indent=2, default=str)

        md_path = out / "investigation.md"
        md_path.write_text(md, encoding="utf-8")
        
        # Create a summary file for quick reference
        summary_path = out / "summary.txt"
        summary_lines = [
            f"Hunt ID: {case_state.get('hunt_id', 'unknown')}",
            f"Entity: {case_state.get('request', {}).get('seed_entity', 'unknown')}",
            f"Generated: {_utcnow_iso()}",
            f"",
            f"Risk Assessment:",
            f"  Judgement: {case_state.get('risk', {}).get('judgement', 'Unknown')}",
            f"  Score: {case_state.get('risk', {}).get('score_0_100', 'N/A')}/100",
            f"",
            f"Deviations: {len(case_state.get('baseline', {}).get('flags', []) or [])}",
            f"Episodes: {len(case_state.get('timeline', {}).get('episodes', []) or [])}",
            f"Evidence Items: {len(case_state.get('evidence_log', []) or [])}",
            f"Pivots: {len(case_state.get('pivots', []) or [])}",
            f"",
            f"Files:",
            f"  - case_state.json (full investigation state)",
            f"  - evidence.jsonl (evidence log)",
            f"  - investigation.md (full report)",
        ]
        summary_path.write_text("\n".join(summary_lines), encoding="utf-8")

        return {
            "success": True,
            "message": f"Wrote hunt artifacts to {out}",
            "data": {
                "hunt_id": case_state.get("hunt_id"),
                "out_dir": str(out.resolve()),
                "case_state_path": str(case_state_path.resolve()),
                "evidence_path": str(evidence_path.resolve()),
                "markdown_report_path": str(md_path.resolve()),
                "summary_path": str(summary_path.resolve()),
            },
        }
    except Exception as e:
        return {"success": False, "message": f"Error writing hunt artifacts: {e}", "data": None}


def save_investigation_output(
    entity: str,
    risk_judgement: str,
    risk_score: int,
    deviations: List[Dict[str, Any]],
    episodes: List[Dict[str, Any]],
    pivots: List[Dict[str, Any]],
    summary: str,
    dataset_root: str = "data/threat_hunting_demo",
) -> Dict[str, Any]:
    """
    Convenience function to save investigation results with proper naming.
    
    Creates a properly named folder under outputs/hunts/ and saves:
    - case_state.json (complete state)
    - evidence.jsonl (evidence references)
    - investigation.md (formatted report)
    - summary.txt (quick reference)
    
    Folder naming format: <entity>_<YYYYMMDD_HHMMSS>
    Example: outputs/hunts/svc_backup1_20250108_161233/
    
    Args:
        entity: The entity being investigated (e.g., "svc_backup1")
        risk_judgement: Risk level (Low/Medium/High/Critical)
        risk_score: Risk score 0-100
        deviations: List of deviation flags from baseline analysis
        episodes: List of timeline episodes
        pivots: List of pivot recommendations
        summary: Executive summary text
        dataset_root: Path to the dataset (default: data/threat_hunting_demo)
        
    Returns:
        Dict with success status and output paths
    """
    try:
        # Generate timestamp and folder name
        now = datetime.now(timezone.utc)
        folder_name = _generate_hunt_folder_name(entity)
        hunt_id = folder_name
        
        # Build case_state structure
        case_state = {
            "hunt_id": hunt_id,
            "request": {
                "seed_entity": entity,
                "dataset_root": dataset_root,
                "start_ts": now.isoformat(),
                "end_ts": now.isoformat(),
            },
            "resolved_entity": {
                "entity_id": entity,
                "entity_type": "service" if entity.startswith("svc_") else "user",
            },
            "baseline": {
                "flags": deviations,
            },
            "timeline": {
                "episodes": episodes,
            },
            "risk": {
                "judgement": risk_judgement,
                "score_0_100": risk_score,
                "explanation": summary,
            },
            "pivots": pivots,
            "evidence_log": [],
        }
        
        # Build evidence log
        evidence_result = build_evidence_log(case_state)
        if evidence_result["success"]:
            case_state = evidence_result["data"]["case_state"]
        
        # Write artifacts
        out_dir = f"{DEFAULT_OUTPUT_BASE}/{folder_name}"
        return write_hunt_artifacts(case_state, out_dir)
        
    except Exception as e:
        return {"success": False, "message": f"Error saving investigation output: {e}", "data": None}
